namespace RecipeHub.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public List<int> Ratings { get; set; } = new();

    public double AverageRating => Ratings.Count > 0 ? Ratings.Average() : 0;
}

using RecipeHub.Models;

namespace RecipeHub.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes = new()
    {
        new Recipe
        {
            Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
            Ingredients = "Pizza dough, San Marzano tomatoes, Fresh mozzarella, Fresh basil, Olive oil, Salt",
            Steps = "1. Preheat oven to 475°F.\n2. Roll out dough on floured surface.\n3. Spread crushed tomatoes evenly.\n4. Tear mozzarella and distribute over sauce.\n5. Bake 10-12 minutes until crust is golden.\n6. Top with fresh basil and drizzle olive oil.",
            Ratings = new List<int> { 5, 4, 5, 4, 5 }
        },
        new Recipe
        {
            Id = 2, Title = "Chicken Tikka Masala", Category = "Indian",
            Ingredients = "Chicken breast, Yogurt, Garam masala, Tomato sauce, Heavy cream, Onion, Garlic, Ginger, Cumin",
            Steps = "1. Marinate chicken in yogurt and spices for 2 hours.\n2. Grill or pan-fry chicken until charred.\n3. Sauté onion, garlic, and ginger.\n4. Add tomato sauce and spices, simmer 15 min.\n5. Stir in cream and cooked chicken.\n6. Serve over basmati rice.",
            Ratings = new List<int> { 5, 5, 4, 5 }
        },
        new Recipe
        {
            Id = 3, Title = "Beef Tacos", Category = "Mexican",
            Ingredients = "Ground beef, Taco seasoning, Corn tortillas, Lettuce, Tomato, Cheddar cheese, Sour cream, Salsa",
            Steps = "1. Brown ground beef in skillet.\n2. Add taco seasoning and water, simmer 5 min.\n3. Warm tortillas in dry pan.\n4. Assemble tacos with beef and toppings.\n5. Serve with salsa and sour cream.",
            Ratings = new List<int> { 4, 4, 5, 3 }
        },
        new Recipe
        {
            Id = 4, Title = "Spaghetti Carbonara", Category = "Italian",
            Ingredients = "Spaghetti, Guanciale, Eggs, Pecorino Romano, Black pepper",
            Steps = "1. Cook spaghetti in salted water until al dente.\n2. Crisp guanciale in a pan.\n3. Whisk eggs with grated Pecorino and pepper.\n4. Toss hot pasta with guanciale off heat.\n5. Quickly stir in egg mixture to create creamy sauce.\n6. Serve immediately with extra Pecorino.",
            Ratings = new List<int> { 5, 5, 5, 4, 5 }
        },
        new Recipe
        {
            Id = 5, Title = "Pad Thai", Category = "Thai",
            Ingredients = "Rice noodles, Shrimp, Eggs, Bean sprouts, Peanuts, Lime, Fish sauce, Tamarind paste, Sugar, Garlic",
            Steps = "1. Soak rice noodles in warm water 30 min.\n2. Make sauce: tamarind, fish sauce, sugar.\n3. Stir-fry shrimp and garlic, set aside.\n4. Scramble eggs in wok.\n5. Add noodles and sauce, toss until coated.\n6. Add shrimp, sprouts, peanuts. Serve with lime.",
            Ratings = new List<int> { 4, 5, 4, 4 }
        },
        new Recipe
        {
            Id = 6, Title = "Guacamole", Category = "Mexican",
            Ingredients = "Avocados, Lime juice, Red onion, Cilantro, Jalapeño, Tomato, Salt, Garlic",
            Steps = "1. Halve and pit avocados.\n2. Mash to desired consistency.\n3. Dice onion, tomato, jalapeño, and cilantro.\n4. Mix all ingredients together.\n5. Season with lime juice and salt.\n6. Serve immediately with tortilla chips.",
            Ratings = new List<int> { 5, 4, 5 }
        },
        new Recipe
        {
            Id = 7, Title = "Green Curry", Category = "Thai",
            Ingredients = "Coconut milk, Green curry paste, Chicken thighs, Thai basil, Bamboo shoots, Fish sauce, Sugar, Eggplant",
            Steps = "1. Heat coconut cream until oil separates.\n2. Fry curry paste until fragrant.\n3. Add chicken, cook 5 min.\n4. Pour in remaining coconut milk.\n5. Add vegetables, simmer until tender.\n6. Season with fish sauce and sugar. Add basil.",
            Ratings = new List<int> { 5, 4, 5, 5 }
        },
        new Recipe
        {
            Id = 8, Title = "Butter Chicken", Category = "Indian",
            Ingredients = "Chicken thighs, Butter, Tomato puree, Cream, Garam masala, Fenugreek leaves, Ginger, Garlic, Chili powder",
            Steps = "1. Marinate chicken in yogurt and spices.\n2. Grill or bake chicken until done.\n3. Make sauce: cook tomatoes with butter and spices.\n4. Blend sauce until smooth.\n5. Add cream and fenugreek leaves.\n6. Add chicken to sauce, simmer 10 min.",
            Ratings = new List<int> { 5, 5, 4, 5, 5 }
        }
    };

    private int _nextId = 9;

    public List<string> GetCategories() =>
        _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();

    public List<Recipe> GetByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetById(int id) =>
        _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe != null && stars >= 1 && stars <= 5)
            recipe.Ratings.Add(stars);
    }

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _nextId++;
        _recipes.Add(recipe);
    }
}

