@page "/category/{CategoryName}"
@using RecipeHub.Services
@using RecipeHub.Models
@inject RecipeService RecipeService

<PageTitle>@CategoryName Recipes - RecipeHub</PageTitle>

<h1>@CategoryName Recipes</h1>

@if (recipes.Any())
{
    <div class="row">
        @foreach (var recipe in recipes)
        {
            <div class="col-md-6 mb-3">
                <div class="card">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="card-text text-muted">
                            ⭐ @recipe.AverageRating.ToString("F1") (@recipe.Ratings.Count ratings)
                        </p>
                        <a href="/recipe/@recipe.Id" class="btn btn-outline-primary">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}
else
{
    <p>No recipes found in this category.</p>
}

<a href="/" class="btn btn-secondary mt-3">← Back to Categories</a>

@code {
    [Parameter]
    public string CategoryName { get; set; } = string.Empty;

    private List<Recipe> recipes = new();

    protected override void OnParametersSet()
    {
        recipes = RecipeService.GetByCategory(CategoryName);
    }
}

@page "/recipe/{Id:int}"
@using RecipeHub.Services
@using RecipeHub.Models
@inject RecipeService RecipeService

<PageTitle>@(recipe?.Title ?? "Recipe") - RecipeHub</PageTitle>

@if (recipe is not null)
{
    <h1>@recipe.Title</h1>
    <span class="badge bg-secondary mb-3">@recipe.Category</span>

    <div class="row mt-3">
        <div class="col-md-4">
            <div class="card">
                <div class="card-header"><strong>Ingredients</strong></div>
                <ul class="list-group list-group-flush">
                    @foreach (var ingredient in recipe.Ingredients.Split(',', StringSplitOptions.TrimEntries))
                    {
                        <li class="list-group-item">@ingredient</li>
                    }
                </ul>
            </div>
        </div>
        <div class="col-md-8">
            <div class="card">
                <div class="card-header"><strong>Instructions</strong></div>
                <div class="card-body">
                    @foreach (var step in recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
                    {
                        <p>@step</p>
                    }
                </div>
            </div>
        </div>
    </div>

    <div class="mt-4">
        <StarRating RecipeId="recipe.Id" CurrentAverage="recipe.AverageRating" RatingCount="recipe.Ratings.Count" />
    </div>

    <a href="/category/@recipe.Category" class="btn btn-secondary mt-3">← Back to @recipe.Category</a>
}
else
{
    <p>Recipe not found.</p>
    <a href="/" class="btn btn-secondary">← Back to Home</a>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private Recipe? recipe;

    protected override void OnParametersSet()
    {
        recipe = RecipeService.GetById(Id);
    }
}

@rendermode InteractiveServer
@using RecipeHub.Services
@inject RecipeService RecipeService

<div class="card p-3">
    <h5>Rate this recipe</h5>
    <div class="d-flex align-items-center gap-1 mb-2">
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <button class="btn btn-link p-0 fs-3 text-decoration-none"
                    @onclick="() => SubmitRating(star)"
                    title="Rate @star stars">
                @(star <= hoveredStar ? "★" : "☆")
            </button>
        }
    </div>
    <p class="text-muted mb-0">
        ⭐ @CurrentAverage.ToString("F1") average (@RatingCount ratings)
        @if (submitted)
        {
            <span class="text-success ms-2">✓ Thanks for rating!</span>
        }
    </p>
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Parameter] public double CurrentAverage { get; set; }
    [Parameter] public int RatingCount { get; set; }

    private int hoveredStar = 0;
    private bool submitted = false;

    private void SubmitRating(int stars)
    {
        RecipeService.AddRating(RecipeId, stars);
        var recipe = RecipeService.GetById(RecipeId);
        if (recipe is not null)
        {
            CurrentAverage = recipe.AverageRating;
            RatingCount = recipe.Ratings.Count;
        }
        hoveredStar = stars;
        submitted = true;
    }
}

@page "/submit"
@rendermode InteractiveServer
@using RecipeHub.Services
@using RecipeHub.Models
@inject RecipeService RecipeService

<PageTitle>Submit a Recipe - RecipeHub</PageTitle>

<h1>📝 Submit a Recipe</h1>
<p>Share your favorite recipe with the community!</p>

@if (successMessage is not null)
{
    <div class="alert alert-success">@successMessage</div>
}

<EditForm Model="newRecipe" OnValidSubmit="HandleSubmit" FormName="submitRecipe">
    <DataAnnotationsValidator />

    <div class="mb-3">
        <label class="form-label">Recipe Title</label>
        <InputText @bind-Value="newRecipe.Title" class="form-control" placeholder="e.g., Grandma's Apple Pie" />
        <ValidationMessage For="() => newRecipe.Title" />
    </div>

    <div class="mb-3">
        <label class="form-label">Category</label>
        <InputSelect @bind-Value="newRecipe.Category" class="form-select">
            <option value="">-- Select a category --</option>
            <option value="Italian">Italian</option>
            <option value="Indian">Indian</option>
            <option value="Mexican">Mexican</option>
            <option value="Thai">Thai</option>
            <option value="American">American</option>
            <option value="French">French</option>
            <option value="Japanese">Japanese</option>
            <option value="Other">Other</option>
        </InputSelect>
        <ValidationMessage For="() => newRecipe.Category" />
    </div>

    <div class="mb-3">
        <label class="form-label">Ingredients</label>
        <InputTextArea @bind-Value="newRecipe.Ingredients" class="form-control" rows="4"
                       placeholder="Comma-separated list, e.g., Flour, Sugar, Butter, Eggs" />
        <ValidationMessage For="() => newRecipe.Ingredients" />
    </div>

    <div class="mb-3">
        <label class="form-label">Steps</label>
        <InputTextArea @bind-Value="newRecipe.Steps" class="form-control" rows="6"
                       placeholder="One step per line, e.g.,&#10;1. Preheat oven to 350°F.&#10;2. Mix dry ingredients..." />
        <ValidationMessage For="() => newRecipe.Steps" />
    </div>

    <button type="submit" class="btn btn-success">Submit Recipe</button>
    <a href="/" class="btn btn-secondary ms-2">Cancel</a>
</EditForm>

@code {
    private Recipe newRecipe = new();
    private string? successMessage;

    private void HandleSubmit()
    {
        if (string.IsNullOrWhiteSpace(newRecipe.Title) ||
            string.IsNullOrWhiteSpace(newRecipe.Category) ||
            string.IsNullOrWhiteSpace(newRecipe.Ingredients) ||
            string.IsNullOrWhiteSpace(newRecipe.Steps))
        {
            return;
        }

        RecipeService.AddRecipe(newRecipe);
        successMessage = $"'{newRecipe.Title}' has been submitted successfully!";
        newRecipe = new();
    }
}

